// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        bound(_feeRate, 0, 5000);
        c.initialize(
            address(0),
            address(0),
            1,
            1,
            0,
            _feeRate,
            bytes32(0),
            false,
            false
        );
        assertTrue(c.feeRate() == _feeRate);
    }
}
